import {HostBluetooth} from './bluetooth-host.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showBluetoothPanel({showDialog,send,packet,active}){
 showDialog('Bluetooth · sanal ağ ve gerçek BLE',`<div class="bt-panel"><p>Devre ağı · <strong>Sanal BLE UART</strong>. Modüller 3.3 V, GND ve UART TX/RX bağlantısı gerektirir. Modül TX → kart RX; kart TX → modül RX. Simülasyonu çalıştırın.</p><button id="bt-scan">Sanal ağı tara</button><p id="bt-status" role="status">${active?'Sanal cihazları aramaya hazır.':'Önce modülü içeren projeyi derleyip çalıştırın.'}</p><label>Hedef<select id="bt-peer"><option value="$pc">Sanal bilgisayar</option></select></label><div id="bt-devices"></div><label>Sanal bilgisayar → modül <input id="bt-input" maxlength="1024" placeholder="Mesaj"></label><button id="bt-send">Gönder ↗</button><pre id="bt-output" aria-label="Sanal Bluetooth alınan veri"></pre><hr><details><summary>Gerçek bilgisayar Bluetooth · BLE GATT</summary><p>Tarayıcı cihaz seçme penceresini açar. Yalnızca izin verdiğiniz BLE GATT cihazına bağlanır; bu alan sanal ağdan bağımsızdır. HC-05/HC-06 Classic SPP ve tüm çevredeki cihazların listelenmesi Web Bluetooth kapsamında değildir.</p><label>Service UUID<input id="bt-service" value="6e400001-b5a3-f393-e0a9-e50e24dcca9e"></label><label>Notify UUID<input id="bt-rx" value="6e400003-b5a3-f393-e0a9-e50e24dcca9e"></label><label>Write UUID<input id="bt-tx" value="6e400002-b5a3-f393-e0a9-e50e24dcca9e"></label><small>Varsayılan: Nordic UART Service. Cihazınızın GATT UUID değerlerini girin.</small><p id="bt-host-status" role="status"></p><button id="bt-host-connect">Gerçek BLE cihazı seç</button><button id="bt-host-disconnect">Bağlantıyı kes</button><input id="bt-host-input" maxlength="512" placeholder="Gerçek cihaza mesaj"><button id="bt-host-send">Gerçek cihaza gönder</button><pre id="bt-host-output" aria-label="Gerçek BLE alınan veri"></pre></details></div>`);
 const $=id=>document.getElementById(id);let selected=null,last=packet,host=new HostBluetooth(),log='',closed=false,renderKey='';const status=message=>{if($('bt-status'))$('bt-status').textContent=message;};
 const render=p=>{if(!p)return;last=p;const devices=p.devices||{},key=JSON.stringify(devices);if(key===renderKey)return;renderKey=key;const old=$('bt-peer').value;$('bt-peer').innerHTML='<option value="$pc">Sanal bilgisayar</option>'+Object.entries(devices).map(([id,d])=>'<option value="'+esc(id)+'">'+esc(d.name)+'</option>').join('');$('bt-peer').value=Object.hasOwn(devices,old)||old==='$pc'?old:'$pc';$('bt-devices').innerHTML=Object.entries(devices).map(([id,d])=>`<div class="property"><span>${esc(d.name)} · ${esc(id)}<small>${d.powered?'3.3 V · '+d.baud+' baud':d.safe===false?'RX aşırı gerilim':'Besleme yok'} · ${d.connected?'Bağlı: '+esc(d.connected):'Bağlı değil'}</small></span><button data-bt-id="${esc(id)}" ${!d.powered?'disabled':''}>${d.connected?'Kes':'Bağlan'}</button></div>`).join('')||'<p>Devreye Bluetooth UART modülü ekleyin.</p>';$('bt-devices').querySelectorAll('[data-bt-id]').forEach(b=>b.onclick=()=>{selected=b.dataset.btId;send({action:devices[selected].connected?'disconnect':'connect',id:selected,peer:$('bt-peer').value});});$('bt-output').textContent=Object.entries(devices).map(([id,d])=>id+' → '+(d.received||'')).join('\n');};render(last);
 $('bt-scan').onclick=()=>{if(!active)return status('Önce simülasyonu çalıştırın.');send({action:'scan'});};$('bt-send').onclick=()=>{const id=selected&&last?.devices[selected]?.connected==='$pc'?selected:Object.keys(last?.devices||{}).find(id=>last.devices[id].connected==='$pc');if(!id)return status('Önce bir sanal cihaza bağlanın.');send({action:'send',id,text:$('bt-input').value+'\n'});$('bt-input').value='';};
 const hostStatus=m=>{if($('bt-host-status'))$('bt-host-status').textContent=m;};$('bt-host-connect').disabled=!host.api?.requestDevice;hostStatus(host.api?.requestDevice?'Gerçek cihaz bağlantısı kullanıcı seçimiyle başlar.':'Bu tarayıcı Web Bluetooth desteklemiyor. HTTPS adresini Chrome/Edge ile açın.');host.onData=bytes=>{log=(log+new TextDecoder().decode(bytes)).slice(-12000);if($('bt-host-output'))$('bt-host-output').textContent=log;};host.onDisconnect=()=>hostStatus('Gerçek BLE bağlantısı kesildi.');$('bt-host-connect').onclick=async()=>{try{hostStatus('Cihaz seçimi / bağlantı…');const name=await host.connect($('bt-service').value.trim(),$('bt-rx').value.trim(),$('bt-tx').value.trim());hostStatus('Bağlı: '+name);}catch(e){hostStatus(e.message);}};$('bt-host-disconnect').onclick=()=>{host.disconnect();hostStatus('Gerçek BLE bağlantısı kesildi.');};$('bt-host-send').onclick=async()=>{try{await host.send($('bt-host-input').value);hostStatus('Mesaj gönderildi.');}catch(e){hostStatus(e.message);}};
 const timer=setInterval(()=>{if(!document.getElementById('bt-status')||!document.getElementById('dialog')?.open){clearInterval(timer);host.disconnect();closed=true;}},250);
 return {update(p,scan){if(closed||!$('bt-status'))return;render(p);if(scan)status(scan.length+' erişilebilir sanal cihaz bulundu.');},error(message){status(message);},dispose(){closed=true;clearInterval(timer);host.disconnect();}};
}
